func ptrHoldReason(p unsafe.Pointer, c int32) any {
	r := (*holdreason.HoldReason)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Type))
	case 4:
		return &r.Code
	case 5:
		return &r.Label
	case 6:
		return &r.Description
	case 7:
		return &r.Active
	case 8:
		return (*string)(unsafe.Pointer(&r.DefaultSeverity))
	case 9:
		return &r.DefaultBlocksDispatch
	case 10:
		return &r.DefaultBlocksDelivery
	case 11:
		return &r.DefaultBlocksBilling
	case 12:
		return &r.DefaultVisibleToCustomer
	case 13:
		return &r.SortOrder
	case 14:
		return &r.ExternalMap
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	case 18:
		return &r.SearchVector
	}
	return nil
}

func valueHoldReason(p unsafe.Pointer, c int32) any {
	r := (*holdreason.HoldReason)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Type)
	case 4:
		return r.Code
	case 5:
		return r.Label
	case 6:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 7:
		return r.Active
	case 8:
		return string(r.DefaultSeverity)
	case 9:
		return r.DefaultBlocksDispatch
	case 10:
		return r.DefaultBlocksDelivery
	case 11:
		return r.DefaultBlocksBilling
	case 12:
		return r.DefaultVisibleToCustomer
	case 13:
		return r.SortOrder
	case 14:
		if r.ExternalMap == nil {
			return nil
		}
		return r.ExternalMap
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	case 18:
		return r.SearchVector
	}
	return nil
}

